// And groups predicates with the AND operator between them.
func And(predicates ...predicate.PlatformSkill) predicate.PlatformSkill {
	return predicate.PlatformSkill(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.PlatformSkill) predicate.PlatformSkill {
	return predicate.PlatformSkill(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.PlatformSkill) predicate.PlatformSkill {
	return predicate.PlatformSkill(sql.NotPredicates(p))
}
